def transform(grid):
    """Color background cells between aligned pairs of matching markers."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    colors = {x for row in grid for x in row if x != background}
    for color in colors:
        # Horizontal intervals between markers of this color.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            if len(cols) >= 2:
                for c in range(cols[0] + 1, cols[-1]):
                    if grid[r][c] == background:
                        out[r][c] = 3
        # Vertical intervals between markers of this color.
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 2:
                for r in range(rows[0] + 1, rows[-1]):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out

